(()=>{'use strict';const icons={add:'add',local:'folder_open','external-sources':'travel_explore','music-addons':'cloud','debrid-source':'link',settings:'settings',connect:'add_link','theme-switch':'palette',profile:'account_circle','like':'favorite_border',shuffle:'shuffle',prev:'skip_previous',play:'play_arrow',next:'skip_next',repeat:'repeat',queue:'queue_music',mute:'volume_up',close:'close'};
function set(id,name){const button=$('#'+id);if(!button)return;const label=button.querySelector('span:not(.material-symbols-rounded)');const text=label?.textContent;button.innerHTML=`<span class="material-symbols-rounded" aria-hidden="true">${name}</span>${text?'<span>'+escapeHTML(text)+'</span>':''}`;if(!button.getAttribute('aria-label'))button.setAttribute('aria-label',button.title||text||name.replaceAll('_',' '))}
for(const [id,name]of Object.entries(icons))set(id,name);
for(const [v,name]of [['discover','home'],['search','search'],['library','library_music'],['liked','favorite']]){const button=document.querySelector('[data-view="'+v+'"]');if(button){const label=button.querySelector('span')?.textContent||v;button.innerHTML='<span class="material-symbols-rounded" aria-hidden="true">'+name+'</span><span>'+escapeHTML(label)+'</span>'}}
for(const event of ['play','pause'])audio.addEventListener(event,()=>set('play',audio.paused?'play_arrow':'pause'));$('#like').addEventListener('click',()=>set('like',liked.has(current)?'favorite':'favorite_border'));$('#mute').addEventListener('click',()=>set('mute',audio.muted?'volume_off':'volume_up'));
})();
